func javaVisibility(access uint16) string {
	if access&jvmPublic != 0 {
		return "public"
	}
	if access&jvmProtected != 0 {
		return "protected"
	}
	return "package"
}

func javaSymbolKind(kind string) option.Option[JavaSymbolKind] {
	switch kind {
	case "class":
		return option.Some[JavaSymbolKind]{Value: JavaClass{}}
	case "interface":
		return option.Some[JavaSymbolKind]{Value: JavaInterface{}}
	case "annotation":
		return option.Some[JavaSymbolKind]{Value: JavaAnnotation{}}
	case "enum":
		return option.Some[JavaSymbolKind]{Value: JavaEnum{}}
	case "field":
		return option.Some[JavaSymbolKind]{Value: JavaField{}}
	case "constructor":
		return option.Some[JavaSymbolKind]{Value: JavaConstructor{}}
	case "method":
		return option.Some[JavaSymbolKind]{Value: JavaMethod{}}
	default:
		return option.None[JavaSymbolKind]{}
	}
}
